#!/usr/bin/env python3
"""
NRII <-> Semismooth Published Impacting-Bar Relay
Scalable Matrix-Free CPU benchmark.

Branch baseline
---------------
* Dense direct verifier is removed from the timed/hot path.
* Full one-bounce-plus-margin runs are performed at Ne = 50, 200, 1000, 5000.
* The smooth bulk update is a fixed-order, one-way NRII implicit-midpoint cascade.
* The unit-impulse response baton is generated by the same Matrix-Free NRII cascade.
* Exact Fischer-Burmeister contact is owned by a semismooth Newton node.
* Ordinary Newton at the exact NCP corner is recorded only as a formulation-domain control.
* CPU timings are measured after Numba JIT warm-up.
* GPU is not benchmarked unless a CUDA device exists. This cloud runtime has no CUDA device;
  a future GPU implementation must not fabricate timings from CPU projections.
"""

import json
import math
import platform
import time
import numpy as np
from numba import njit

L = 0.254
AREA = 6.45e-4
YOUNG = 211e9
RHO = 7847.0
V0 = 5.0
REST = 0.0

ORDER = 64
RESPONSE_ORDER = 64
TOL = 1e-9
NCP_TOL = 1e-13

@njit(cache=True)
def stiffness(u, out, ke):
    n = u.shape[0]
    out[0] = ke * (u[0] - u[1])
    for i in range(1, n-1):
        out[i] = ke * (2.0*u[i] - u[i-1] - u[i+1])
    out[n-1] = ke * (u[n-1] - u[n-2])

@njit(cache=True)
def fb(p, w):
    return math.sqrt(p*p + w*w) - p - w

@njit(cache=True)
def semismooth_contact(b, W, tol=NCP_TOL, maxit=30):
    p = 0.0
    w = 0.0
    for it in range(maxit + 1):
        f1 = fb(p, w)
        f2 = w - (b + W*p)
        nF = math.sqrt(f1*f1 + f2*f2)
        if nF <= tol:
            return 1, it, p, w, nF

        r = math.sqrt(p*p + w*w)
        if r > 1e-30:
            a = p/r - 1.0
            c = w/r - 1.0
        else:
            a = -1.0
            c = -1.0

        # [a c; -W 1] [dp,dw] = -[f1,f2]
        det = a + c*W
        if abs(det) < 1e-30:
            return -1, it, p, w, nF

        dp = (-f1 + c*f2) / det
        dw = (-a*f2 - W*f1) / det

        alpha = 1.0
        accepted = False
        for _ in range(40):
            pn = p + alpha*dp
            wn = w + alpha*dw
            g1 = fb(pn, wn)
            g2 = wn - (b + W*pn)
            nGn = math.sqrt(g1*g1 + g2*g2)
            if nGn <= (1.0 - 1e-4*alpha)*nF or alpha < 1e-12:
                p = pn
                w = wn
                accepted = True
                break
            alpha *= 0.5
        if not accepted:
            return -2, it, p, w, nF
    return 0, maxit, p, w, math.sqrt(fb(p,w)**2 + (w-(b+W*p))**2)

@njit(cache=True)
def build_mass_inv(ne):
    n = ne + 1
    he = L / ne
    me = RHO * AREA * he
    invm = np.empty(n)
    for i in range(n):
        m = me
        if i == 0 or i == n-1:
            m *= 0.5
        invm[i] = 1.0 / m
    ke = YOUNG * AREA / he
    return invm, ke

@njit(cache=True)
def precompute_response(ne, dt, order):
    invm, ke = build_mass_inv(ne)
    n = ne + 1

    ru = np.zeros(n)
    rv = np.zeros(n)
    tu = np.zeros(n)
    tv = np.zeros(n)
    nu = np.zeros(n)
    nv = np.zeros(n)
    kbuf = np.zeros(n)

    tv[0] = invm[0]
    rv[0] = invm[0]

    half = 0.5 * dt

    for _ord in range(1, order + 1):
        # next term = (dt/2) A term
        for i in range(n):
            nu[i] = half * tv[i]
        stiffness(tu, kbuf, ke)
        for i in range(n):
            nv[i] = -half * kbuf[i] * invm[i]

        for i in range(n):
            ru[i] += nu[i]
            rv[i] += nv[i]
            tu[i] = nu[i]
            tv[i] = nv[i]

    # audit r - B - dt/2 A r
    stiffness(ru, kbuf, ke)
    max_abs = 0.0
    max_scale = 0.0
    for i in range(n):
        bu = 0.0
        bv = invm[0] if i == 0 else 0.0
        resu = ru[i] - bu - half*rv[i]
        resv = rv[i] - bv + half*kbuf[i]*invm[i]
        ar = abs(resu)
        if ar > max_abs: max_abs = ar
        ar = abs(resv)
        if ar > max_abs: max_abs = ar
        sc = abs(ru[i])
        if sc > max_scale: max_scale = sc
        sc = abs(rv[i])
        if sc > max_scale: max_scale = sc

    rel = max_abs / max(max_scale, 1e-30)
    return ru, rv, rv[0], rel

@njit(cache=True)
def simulate(ne, dt, duration, order, response_order):
    invm, ke = build_mass_inv(ne)
    n = ne + 1
    steps = int(math.ceil(duration / dt))

    # state
    u = np.zeros(n)
    v = np.empty(n)
    for i in range(n):
        v[i] = -V0

    # work buffers
    u1 = np.zeros(n)
    v1 = np.zeros(n)
    tu = np.zeros(n)
    tv = np.zeros(n)
    nu = np.zeros(n)
    nv = np.zeros(n)
    kbuf0 = np.zeros(n)
    kbuf1 = np.zeros(n)

    # response baton
    resp_u, resp_v, W, response_resid = precompute_response(ne, dt, response_order)

    contact_forces = np.zeros(steps)
    contact_count = 0
    corner_hard_fails = 0
    max_ncp_resid = 0.0
    max_comp = 0.0
    max_free_resid = 0.0
    first_release_step = -1
    contact_started = False

    half = 0.5 * dt

    for step in range(steps):
        # candidate starts at y0
        for i in range(n):
            u1[i] = u[i]
            v1[i] = v[i]

        # t1 = dt A y0
        for i in range(n):
            tu[i] = dt * v[i]
        stiffness(u, kbuf0, ke)
        for i in range(n):
            tv[i] = -dt * kbuf0[i] * invm[i]
            u1[i] += tu[i]
            v1[i] += tv[i]

        # higher NRII coefficients / terms
        for _ord in range(2, order + 1):
            for i in range(n):
                nu[i] = half * tv[i]
            stiffness(tu, kbuf1, ke)
            for i in range(n):
                nv[i] = -half * kbuf1[i] * invm[i]

            for i in range(n):
                u1[i] += nu[i]
                v1[i] += nv[i]
                tu[i] = nu[i]
                tv[i] = nv[i]

        # residual audit only
        stiffness(u1, kbuf1, ke)
        max_abs = 0.0
        max_scale = 0.0
        for i in range(n):
            ru = u1[i] - u[i] - half*(v[i] + v1[i])
            rv = v1[i] - v[i] + half*(kbuf0[i] + kbuf1[i])*invm[i]
            a = abs(ru)
            if a > max_abs: max_abs = a
            a = abs(rv)
            if a > max_abs: max_abs = a
            s = abs(u1[i] - u[i])
            if s > max_scale: max_scale = s
            s = abs(v1[i] - v[i])
            if s > max_scale: max_scale = s
        rel = max_abs / max(max_scale, 1e-30)
        if rel > max_free_resid:
            max_free_resid = rel

        # published Moreau-Jean active-set predictor
        predicted_gap = u[0] + dt*v[0]
        active = predicted_gap <= 0.0

        if active:
            contact_started = True
            b = v1[0] + REST*v[0]

            # Strict ordinary Newton on exact FB at (0,0) is undefined whenever
            # the NCP residual is nonzero.
            if abs(b) > NCP_TOL:
                corner_hard_fails += 1

            status, it, p, w, ncp_res = semismooth_contact(b, W)
            if status != 1:
                return (-1, step, max_free_resid, response_resid,
                        max_ncp_resid, max_comp, contact_count,
                        corner_hard_fails, first_release_step,
                        contact_forces)

            for i in range(n):
                u1[i] += resp_u[i] * p
                v1[i] += resp_v[i] * p

            contact_forces[contact_count] = p / dt
            contact_count += 1
            if ncp_res > max_ncp_resid:
                max_ncp_resid = ncp_res
            cp = abs(p*w)
            if cp > max_comp:
                max_comp = cp
        else:
            if contact_started and first_release_step < 0:
                first_release_step = step

        # commit by swapping numerical contents
        for i in range(n):
            u[i] = u1[i]
            v[i] = v1[i]

    return (1, steps, max_free_resid, response_resid,
            max_ncp_resid, max_comp, contact_count,
            corner_hard_fails, first_release_step,
            contact_forces)

def wave_speed():
    return math.sqrt(YOUNG/RHO)

def tb():
    return 2.0*L/wave_speed()

def F0():
    return RHO*wave_speed()*V0*AREA

def run_case(ne):
    dt = 0.7*(L/ne)/wave_speed()
    duration = 1.25*tb()

    t0 = time.perf_counter()
    result = simulate(ne, dt, duration, ORDER, RESPONSE_ORDER)
    elapsed = time.perf_counter() - t0

    (status, steps, free_resid, response_resid,
     ncp_resid, comp, contact_count, corner_fails,
     release_step, forces) = result

    if status != 1:
        raise RuntimeError(f"simulation failed ne={ne} at step={steps}")

    if contact_count > 0:
        fvals = np.asarray(forces[:contact_count])
        median_force = float(np.median(fvals))
        mean_force = float(np.mean(fvals))
    else:
        median_force = float("nan")
        mean_force = float("nan")

    release_time = (release_step + 1)*dt if release_step >= 0 else float("nan")
    dof = 2*(ne+1)

    return {
        "Ne": ne,
        "DOF": dof,
        "dt_s": dt,
        "duration_s": duration,
        "steps": int(steps),
        "wall_time_s": elapsed,
        "steps_per_second": float(steps/elapsed),
        "dof_steps_per_second": float(dof*steps/elapsed),
        "ns_per_dof_step": float(elapsed*1e9/(dof*steps)),
        "release_time_over_tb": float(release_time/tb()),
        "median_force_over_F0": float(median_force/F0()),
        "mean_force_over_F0": float(mean_force/F0()),
        "contact_steps": int(contact_count),
        "ordinary_newton_exact_FB_corner_hard_fails": int(corner_fails),
        "max_NRII_residual_rel_inf": float(free_resid),
        "ImpulseResponseBaton_residual_rel_inf": float(response_resid),
        "max_NCP_residual": float(ncp_resid),
        "max_complementarity_product_abs": float(comp),
        "NRII_order": ORDER,
        "response_order": RESPONSE_ORDER,
    }

def first_step_domain_conflict(ne=50):
    dt = 0.7*(L/ne)/wave_speed()
    invm, ke = build_mass_inv(ne)
    n = ne+1

    # one smooth fixed-order step, no contact
    u = np.zeros(n)
    v = np.full(n, -V0)

    u1 = u.copy()
    v1 = v.copy()
    tu = dt*v.copy()
    kbuf = np.empty(n)
    stiffness(u, kbuf, ke)
    tv = -dt*kbuf*invm
    u1 += tu
    v1 += tv
    half = 0.5*dt

    for _ in range(2, ORDER+1):
        nu = half*tv
        stiffness(tu, kbuf, ke)
        nv = -half*kbuf*invm
        u1 += nu
        v1 += nv
        tu, tv = nu, nv

    stiffness(u1, kbuf, ke)
    ru = u1-u-half*(v+v1)
    # initial stiffness is zero
    rv = v1-v+half*kbuf*invm
    res = max(np.max(np.abs(ru)), np.max(np.abs(rv)))
    scale = max(np.max(np.abs(u1-u)), np.max(np.abs(v1-v)), 1e-30)

    return {
        "Ne": ne,
        "dt_s": dt,
        "free_contact_node_displacement_m": float(u1[0]),
        "unilateral_domain_valid": bool(u1[0] >= 0.0),
        "NRII_relative_residual": float(res/scale),
        "NRII_order": ORDER,
    }

def main():
    # Warm-up: compile all hot kernels before timing.
    _ = simulate(8, 0.7*(L/8)/wave_speed(), 4*0.7*(L/8)/wave_speed(), ORDER, RESPONSE_ORDER)

    scaling = []
    for ne in (50, 200, 1000, 5000):
        scaling.append(run_case(ne))

    out = {
        "test_name": "NRII-Semismooth Published Impacting-Bar Relay Matrix-Free Scaling",
        "runtime": {
            "python": platform.python_version(),
            "platform": platform.platform(),
            "cuda_measured": False,
            "cuda_reason": "No CUDA device is exposed by this cloud runtime; GPU timings are intentionally not fabricated.",
            "cpu_backend": "Numba JIT + NumPy arrays",
        },
        "published_parameter_lock": {
            "L_m": L,
            "A_m2": AREA,
            "E_Pa": YOUNG,
            "rho_kg_m3": RHO,
            "launch_speed_mps": V0,
            "restitution_e": REST,
            "CFL_fraction": 0.7,
            "analytical_wave_speed_mps": wave_speed(),
            "analytical_bounce_time_s": tb(),
            "analytical_force_scale_N": F0(),
        },
        "solver_contract": {
            "smooth_bulk": "Matrix-Free fixed-order NRII implicit-midpoint coefficient cascade",
            "contact": "Exact Fischer-Burmeister semismooth Newton",
            "baton": "Matrix-Free NRII ImpulseResponseBaton",
            "dense_hot_path": False,
            "NRII_residual_role": "audit/gate only; never a state correction",
        },
        "first_step_domain_conflict": first_step_domain_conflict(50),
        "scaling": scaling,
        "guardrails": [
            "The timed hot path contains no dense matrix assembly, factorization, or dense direct solve.",
            "NRII is fixed order in branch. Residual is audited after candidate generation and does not drive corrections.",
            "Contact uses a separate generalized-Jacobian semismooth node.",
            "Strict ordinary Newton on exact Fischer-Burmeister at (0,0) is undefined; this does not imply all Newton-family methods fail.",
            "CPU timings are measured after JIT warm-up.",
            "No GPU timing is reported because this cloud runtime exposes no CUDA device.",
            "This is a published-parameter/equation benchmark adaptation rather than a bitwise reproduction of an external implementation.",
        ],
    }

    print(json.dumps(out, indent=2))

if __name__ == "__main__":
    main()
